#!/usr/bin/env python3
import sys

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    filename = sys.argv[1]
    feature_counts = {}
    total_cds_bp = 0

    with open(filename, 'r') as f:
        for line in f:
            line = line.strip()
            # Skip blank lines and comment lines
            if not line or line.startswith('#'):
                continue

            # Split by tab
            fields = line.split('\t')
            if len(fields) < 3:
                continue

            feature_type = fields[2]
            start = int(fields[3])
            end = int(fields[4])

            # Count by type
            feature_counts[feature_type] = feature_counts.get(feature_type, 0) + 1

            # Sum CDS lengths
            if feature_type == 'CDS':
                cds_length = end - start + 1
                total_cds_bp += cds_length

    # Print sorted feature counts
    for feature_type in sorted(feature_counts.keys()):
        print(f"{feature_type}\t{feature_counts[feature_type]}")

    # Print total CDS bp
    print(f"total_cds_bp\t{total_cds_bp}")

if __name__ == '__main__':
    main()
